import { ConflictError, ValidationError } from "./errors";
import { TaskStatus } from "./task-status";

export interface TaskProps {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate: Date | null;
  status: TaskStatus;
  assigneeId: string | null;
}

export class Task {
  private constructor(private props: TaskProps) {}

  static create(props: Omit<TaskProps, "status" | "assigneeId">): Task {
    if (props.title.trim() === "") {
      throw new ValidationError("title must not be empty");
    }
    if (props.dueDate !== null && Number.isNaN(props.dueDate.getTime())) {
      throw new ValidationError("dueDate must be a valid date");
    }
    return new Task({ ...props, status: "todo", assigneeId: null });
  }

  get id(): string {
    return this.props.id;
  }

  get projectId(): string {
    return this.props.projectId;
  }

  get title(): string {
    return this.props.title;
  }

  get description(): string {
    return this.props.description;
  }

  get dueDate(): Date | null {
    return this.props.dueDate;
  }

  get status(): TaskStatus {
    return this.props.status;
  }

  get assigneeId(): string | null {
    return this.props.assigneeId;
  }

  assignTo(userId: string): void {
    this.props.assigneeId = userId;
  }

  markDone(): void {
    if (this.props.status === "done") {
      throw new ConflictError("task is already done");
    }
    this.props.status = "done";
  }
}

